  function money(n){return new Intl.NumberFormat("en-MY",{style:"currency",currency:"MYR"}).format(n);}
  function product(id){return products.find(function(p){return p.id===id;});}
  function defaultVariant(p){return p.variants.find(function(v){return v.id==="medium";})||p.variants[0];}
  function variant(p,id){return p&&p.variants.find(function(v){return v.id===id;});}
  function sku(p,v){return p.id+"~"+v.id;}
  function cartLine(key){var bits=key.split("~"),p=product(bits[0]),v=variant(p,bits[1]);return p&&v?{key:key,product:p,variant:v,quantity:cart[key]||0}:null;}
  function cartLines(){return Object.keys(cart).map(cartLine).filter(Boolean);}
  function qty(key){return cart[key]||0;}
  function count(){return cartLines().reduce(function(n,line){return n+line.quantity;},0);}
  function subtotal(){return cartLines().reduce(function(n,line){return n+line.variant.price*line.quantity;},0);}
  function discount(){return subtotal()>=discountThreshold?Math.min(discountCap,Math.round(subtotal()*discountRate*100)/100):0;}
  function delivery(){return subtotal()>=freeThreshold[checkoutZone]?0:deliveryFee[checkoutZone];}
  function total(){return subtotal()-discount()+delivery();}
  function loadCart(){try{var raw=JSON.parse(localStorage.getItem("ikanza-demo-cart")||"{}"),safe={};if(!raw||typeof raw!=="object"||Array.isArray(raw))return safe;products.forEach(function(p){p.variants.forEach(function(v){var key=sku(p,v),n=Number(raw[key]);if(Number.isInteger(n)&&n>0)safe[key]=Math.min(n,99);});var old=Number(raw[p.id]);if(Number.isInteger(old)&&old>0){var key=sku(p,defaultVariant(p));safe[key]=Math.min(99,(safe[key]||0)+old);}});return safe;}catch(_){return {};}}
  function saveCart(){localStorage.setItem("ikanza-demo-cart",JSON.stringify(cart));}
