  function escapeHtml(s){return String(s).replace(/[&<>"']/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c];});}
  function safeDecode(s){try{return decodeURIComponent(s);}catch(_){return "";}}
  function announce(s){announcer.textContent="";setTimeout(function(){announcer.textContent=s;},20);}
  function notify(s){var n=document.getElementById("toast");if(n){n.textContent=s;n.classList.add("show");clearTimeout(notify.timer);notify.timer=setTimeout(function(){n.classList.remove("show");},3000);}announce(s);}
  function demoDates(){var list=[],d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()+3);while(list.length<2){if(d.getDay()===3||d.getDay()===6)list.push(d.toLocaleDateString("en-MY",{weekday:"long",day:"numeric",month:"long",year:"numeric"}));d.setDate(d.getDate()+1);}return list;}
  function pricingNote(){return '<p class="pricing-note"><strong>Guide prices checked against Malaysian shops on 29 October 2026.</strong> See the market listing on each product page, or browse <a href="https://pasarhub.my/product-category/fish/" target="_blank" rel="noopener noreferrer">PasarHub fish</a>, <a href="https://pasarhub.my/product-category/seafood/" target="_blank" rel="noopener noreferrer">PasarHub seafood</a> and <a href="https://myseafoodmart.com/index.php?path=84&amp;route=product%2Fcategory" target="_blank" rel="noopener noreferrer">MySeafoodMart shellfish</a>. Some pack weights and prices are estimates. Ikanza stock, preparation, condition, delivery and actual prices are unconfirmed.</p>';}
  function offerTeaser(){return '<div class="offer-teaser"><span class="offer-kicker">Example offers</span><strong>Free delivery from RM250 in Klang Valley or RM400 elsewhere in Peninsular Malaysia</strong><span>Spend RM500 on items for an extra 5% off (up to RM50).</span><small>Preview math only. Real delivery costs and offers depend on the Semporna cold chain and are not available yet.</small></div>';}
  function promoProgress(){var remain=Math.max(0,freeThreshold[checkoutZone]-subtotal()),extra=Math.max(0,discountThreshold-subtotal());return '<div class="promo-progress"><strong>'+(remain?money(remain)+' away from example free delivery':'Example free delivery unlocked')+'</strong><span>'+(extra?money(extra)+' away from the extra 5% example discount':'Extra 5% example discount unlocked')+'</span><small>Based on item subtotal and '+(checkoutZone==="klang"?'Klang Valley':'other Peninsular area')+' example delivery.</small></div>';}
  function normalise(value){return String(value).normalize("NFKD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9\u3400-\u9fff]+/g," ").trim();}
  function oneEditAway(a,b){if(Math.abs(a.length-b.length)>1)return false;var i=0,j=0,edits=0;while(i<a.length&&j<b.length){if(a[i]===b[j]){i++;j++;continue;}if(++edits>1)return false;if(a.length>b.length)i++;else if(b.length>a.length)j++;else{i++;j++;}}return edits+(a.length-i)+(b.length-j)<=1;}
  function searchScore(p,query){if(!query)return 1;var category=categories.find(function(c){return c.id===p.category;}),words=[p.name,p.local,p.kind,category&&category.label].concat(p.aliases||[]).map(normalise),best=0;words.forEach(function(word){if(!word)return;if(word===query)best=Math.max(best,100);else if(word.indexOf(query)===0)best=Math.max(best,80);else if(word.indexOf(query)>=0)best=Math.max(best,60);else if(/^[a-z ]{4,}$/.test(query)){word.split(" ").forEach(function(part){if(part.length>=4&&oneEditAway(part,query))best=Math.max(best,35);});}});return best;}
